// Hospital help assistant. Uses an FAQ matcher by default; if ANTHROPIC_API_KEY is set,
// answers are generated by Claude grounded on the hospital profile + FAQ (no medical diagnosis).
import { config } from '../config.js';
import { hospital } from '../hospital.js';
import { triage } from './triage.js';

const timings = () => hospital.timings.map((t) => `${t.days}: ${t.hours}`).join('\n');

const FAQ = [
  { id: 'book', words: ['book', 'appointment', 'consult', 'see a doctor', 'slot'],
    answer: () => 'You can book from the Book tab: pick a speciality, choose a doctor and a time slot, then pay online or choose "Pay at hospital".', action: { type: 'navigate', to: 'book' } },
  { id: 'timings', words: ['timing', 'open', 'hours', 'close', 'sunday', 'working'],
    answer: () => `Our OPD timings are:\n${timings()}\nEmergency: ${hospital.emergencyPhone}` },
  { id: 'location', words: ['where', 'address', 'location', 'direction', 'reach', 'map', 'parking'],
    answer: () => `${hospital.name}\n${hospital.address}`, action: hospital.mapsUrl ? { type: 'open_url', url: hospital.mapsUrl } : undefined },
  { id: 'contact', words: ['phone', 'call', 'contact', 'number', 'whatsapp', 'email'],
    answer: () => `Reception: ${hospital.phone}\nEmergency: ${hospital.emergencyPhone}\nEmail: ${hospital.email}`, action: { type: 'call', phone: hospital.phone } },
  { id: 'insurance', words: ['insurance', 'cashless', 'tpa', 'claim', 'mediclaim'], answer: () => hospital.insurance },
  { id: 'reports', words: ['report', 'prescription', 'result', 'records', 'glasses power', 'download'],
    answer: () => 'Your eye test results, glasses prescriptions and reports appear in the Records tab once the hospital uploads them. You can view and share them from there.', action: { type: 'navigate', to: 'records' } },
  { id: 'dilation', words: ['dilat', 'drops', 'pupil', 'drive after'],
    answer: () => 'If your pupils are dilated during the exam, your vision may be blurry and sensitive to light for 4–6 hours. Please bring sunglasses and avoid driving yourself home.' },
  { id: 'prepare', words: ['bring', 'prepare', 'first visit', 'documents', 'what to carry'],
    answer: () => 'Please bring your current glasses or contact lenses, previous eye reports, a list of your medicines, and an ID. If you have diabetes or blood pressure, bring recent reports. Arrive 15 minutes early.' },
  { id: 'cataract', words: ['cataract surgery', 'lens implant', 'iol'],
    answer: () => 'Cataract surgery is usually a short day-care procedure. Your surgeon will advise on the type of lens (IOL) that suits you after a full eye check. Book a consultation in the Cataract department for an assessment and cost estimate.' },
  { id: 'lasik', words: ['lasik', 'remove glasses', 'laser', 'smile', 'prk'],
    answer: () => 'Suitability for LASIK or other laser vision correction depends on your age, stable glasses power and corneal thickness. Book a Refractive Surgery consultation for a detailed evaluation.' },
  { id: 'cancel', words: ['cancel', 'reschedule', 'change appointment', 'refund'],
    answer: () => `Open the Appointments tab, choose your appointment, and tap Reschedule or Cancel (allowed up to ${config.booking.cancelCutoffHours} hours before the slot). Online payments for cancelled appointments are refunded to the original payment method.`, action: { type: 'navigate', to: 'appointments' } },
];

const SYMPTOM_HINTS = ['pain', 'red', 'blur', 'itch', 'water', 'vision', 'floater', 'flash', 'swelling', 'injury', 'see', 'sore', 'burning'];

function faqAnswer(message) {
  const t = message.toLowerCase();
  // Safety first: emergencies always win over FAQ matching.
  const urgent = triage({ symptoms: message });
  if (urgent.urgency === 'emergency') {
    return {
      reply: `${urgent.title}.\n${urgent.advice.join('\n')}\nEmergency: ${hospital.emergencyPhone}\n\n${urgent.disclaimer}`,
      action: { type: 'call', phone: hospital.emergencyPhone }, triage: urgent, source: 'triage',
    };
  }
  const scored = FAQ.map((f) => ({ f, s: f.words.filter((w) => t.includes(w)).length })).sort((a, b) => b.s - a.s);
  if (scored[0].s > 0) {
    const { f } = scored[0];
    return { reply: f.answer(), action: f.action, source: 'faq' };
  }
  if (SYMPTOM_HINTS.some((w) => t.includes(w))) {
    const r = triage({ symptoms: message });
    return {
      reply: `${r.title}.\n${r.advice.join('\n')}\n\n${r.disclaimer}`,
      action: r.urgency === 'emergency' ? { type: 'call', phone: hospital.emergencyPhone } : { type: 'navigate', to: 'book', department: r.department },
      triage: r,
      source: 'triage',
    };
  }
  return {
    reply: `I can help with booking appointments, timings, location, reports, insurance and common eye-care questions. For anything else please call ${hospital.phone}.`,
    source: 'fallback',
  };
}

export async function answer(message, history = []) {
  const base = faqAnswer(message);
  // Emergencies are never delegated to the model.
  if (!config.ai.anthropicApiKey || base.triage?.urgency === 'emergency') return base;
  try {
    const system = `You are the virtual help desk of ${hospital.name}, an eye hospital in India.
Answer briefly (max 120 words) and politely in the user's language. Only use the facts below; if you don't know, ask them to call ${hospital.phone}.
Never diagnose or prescribe. For pain, injury, chemical splash, sudden vision loss, flashes/curtain: tell them to call ${hospital.emergencyPhone} or come to emergency immediately.
Hospital facts:
Address: ${hospital.address}
Timings: ${timings()}
Insurance: ${hospital.insurance}
FAQ:
${FAQ.map((f) => `- ${f.id}: ${f.answer()}`).join('\n')}`;
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-api-key': config.ai.anthropicApiKey, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({
        model: config.ai.model,
        max_tokens: 400,
        system,
        messages: [...history.slice(-6), { role: 'user', content: message }],
      }),
    });
    if (!res.ok) return base;
    const data = await res.json();
    const text = data.content?.find((c) => c.type === 'text')?.text;
    return text ? { ...base, reply: text, source: 'ai' } : base;
  } catch {
    return base;
  }
}
